mapper.select:
SELECT /* ============ 🔑 内部追踪 ID（雪花 ID 字符串，CAST AS CHAR） ============ */ CAST(aci.id AS CHAR) AS chargeItemId, CAST(rec.id AS CHAR) AS paymentId,
/* ============ 🏥 就诊级展示字段 ============ */ enc.bus_no AS outpatientNo, pat.name AS patientName, org.name AS deptName, -- ❌ enc.occurrence_time 不存在，改为 enc.start_time（挂号/就诊开始时间） DATE_FORMAT(enc.start_time, '%Y-%m-%d') AS encounterDate,
/* ============ 📋 收费项级展示字段 ============ */ -- 费用大类 code：🔴 优先取 aci.product_table 对应的分类（100% 准确），def.type_code 兜底 -- 注意：med_medication_definition（药品）的 def.type_code 常常是 1001/1003，不是 200x！ CASE WHEN aci.product_table = 'med_medication_definition' THEN COALESCE(def.type_code, '2000') WHEN aci.product_table = 'adm_device_definition' THEN COALESCE(def.type_code, '3000') WHEN aci.product_table = 'wkf_activity_definition' THEN COALESCE(def.type_code, '1000') WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN COALESCE(def.type_code, '1010') ELSE COALESCE(def.type_code, '9999') END AS feeCategoryCode, -- 费用大类展示：🔴 优先 product_table 判断（最准），def.type_code 前缀兜底 CASE WHEN aci.product_table = 'med_medication_definition' THEN '药品' WHEN aci.product_table = 'adm_device_definition' THEN '耗材' WHEN aci.product_table = 'wkf_activity_definition' THEN '医疗服务' WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN '挂号' WHEN def.type_code LIKE '101%' THEN '挂号' WHEN def.type_code LIKE '100%' THEN '医疗服务' WHEN def.type_code LIKE '200%' THEN '药品' WHEN def.type_code LIKE '3%' THEN '耗材' ELSE '其他' END AS feeCategoryDisplay, -- 细分类 code：def 表暂缺 sub_type_code，暂时与 feeCategoryCode 一致 CASE WHEN aci.product_table = 'med_medication_definition' THEN COALESCE(def.type_code, '2000') WHEN aci.product_table = 'adm_device_definition' THEN COALESCE(def.type_code, '3000') WHEN aci.product_table = 'wkf_activity_definition' THEN COALESCE(def.type_code, '1000') WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN COALESCE(def.type_code, '1010') ELSE COALESCE(def.type_code, '9999') END AS subCategoryCode, -- 细分类展示：暂时与 feeCategoryDisplay 一致 CASE WHEN aci.product_table = 'med_medication_definition' THEN '药品' WHEN aci.product_table = 'adm_device_definition' THEN '耗材' WHEN aci.product_table = 'wkf_activity_definition' THEN '医疗服务' WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN '挂号' WHEN def.type_code LIKE '101%' THEN '挂号' WHEN def.type_code LIKE '100%' THEN '医疗服务' WHEN def.type_code LIKE '200%' THEN '药品' WHEN def.type_code LIKE '3%' THEN '耗材' ELSE '其他' END AS subCategoryDisplay, -- 项目名称：3 张产品表 name → def.charge_name → 挂号兜底"挂号费" -- ❌ aci.name_text 不存在，已删除！ CASE WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN COALESCE(def.charge_name, '挂号费') ELSE COALESCE(wkf.name, med.name, dev.name, def.charge_name, '未命名项目') END AS productName, -- 院内编码：3 张产品表 bus_no（def 表没有 bus_no） COALESCE(wkf.bus_no, med.bus_no, dev.bus_no) AS productCode, -- ❌ 规格：med/dev/wkf 3 张表都没有 specification 字段，暂返回 NULL，后续接字典再补 NULL AS specification, aci.quantity_value AS quantityValue, -- 🔴 Bug 2 修复：数量单位不能直接返回 aci.quantity_unit（是数字字典 code，比如 8=瓶，会显示"8"而不是"瓶"） -- 优先顺序： -- 1. 3 张产品表 def_encounter_unit_code（门诊计价单位）查 ter_concept 字典 display -- 2. 找不到用 aci.quantity_unit 查字典 -- 3. 字典没匹配兜底返回数字 code（aci.quantity_unit） -- 字典：ter_concept.code_system_id = 279125561775755265（unit_code 单位编码，2026-07-26 数据库实锤） COALESCE( (SELECT tc.display FROM ter_concept tc WHERE tc.code_system_id = 279125561775755265 AND tc.is_deleted = 0 AND tc.is_active = 1 AND tc.code = COALESCE(wkf.def_encounter_unit_code, med.def_encounter_unit_code, dev.def_encounter_unit_code) LIMIT 1), (SELECT tc.display FROM ter_concept tc WHERE tc.code_system_id = 279125561775755265 AND tc.is_deleted = 0 AND tc.is_active = 1 AND tc.code = aci.quantity_unit LIMIT 1), aci.quantity_unit ) AS quantityUnitDisplay, aci.unit_price AS unitPrice, CAST(doc.id AS CHAR) AS orderingDoctorId, doc.name AS orderingDoctorName, -- 🔴 收银员跨两张表：whale_users（系统用户）+ adm_practitioner（医护用户） -- 实锤：rec.enterer_id=308791351298756608（admin）在 adm_practitioner 里，不在 whale_users； -- rec.enterer_id=1（admin）在 whale_users 里，不在 adm_practitioner COALESCE(CAST(cashier.id AS CHAR), CAST(prac_cashier.id AS CHAR)) AS cashierId, COALESCE(cashier.name, prac_cashier.name) AS cashierName, DATE_FORMAT(rec.bill_date, '%Y-%m-%d %H:%i:%s') AS billDate, -- 收退方向：aci.refund_id 判断（rec.kind_enum 根本没有 REFUND 值！） CASE WHEN aci.refund_id IS NOT NULL THEN 'REFUND' ELSE 'CHARGE' END AS tradeDirection, aci.generate_source_enum AS sourceDisplay, enc.yb_class_text AS insuranceLevelDisplay, -- 医保类型：def.yb_type（真实字段，目前数据全 NULL，后续字典翻译） def.yb_type AS insuranceTypeDisplay, -- 折扣率：折后金额 ÷ 原价 × 100（折后 = 原价 - 优惠） -- 例如：原价2.85，优惠2.85 → 折后0 → 折扣率 0%（正确）；原价5，优惠0 → 折后5 → 100% CASE WHEN COALESCE(aci.base_amount, 0) = 0 THEN '0%' ELSE CONCAT(ROUND((aci.base_amount - aci.discount_amount) / aci.base_amount * 100, 0), '%') END AS discountRateDisplay,
,
ORDER BY rec.bill_date DESC, aci.id DESC

SELECT /* ============ 🔑 内部追踪 ID（雪花 ID 字符串，CAST AS CHAR） ============ */ CAST(aci.id AS CHAR) AS chargeItemId, CAST(rec.id AS CHAR) AS paymentId,
/* ============ 🏥 就诊级展示字段 ============ */ enc.bus_no AS outpatientNo, pat.name AS patientName, org.name AS deptName, DATE_FORMAT(enc.start_time, '%Y-%m-%d') AS encounterDate,
/* ============ 📋 收费项级展示字段 ============ */ CASE WHEN aci.product_table = 'med_medication_definition' THEN COALESCE(def.type_code, '2000') WHEN aci.product_table = 'adm_device_definition' THEN COALESCE(def.type_code, '3000') WHEN aci.product_table = 'wkf_activity_definition' THEN COALESCE(def.type_code, '1000') WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN COALESCE(def.type_code, '1010') ELSE COALESCE(def.type_code, '9999') END AS feeCategoryCode, CASE WHEN aci.product_table = 'med_medication_definition' THEN '药品' WHEN aci.product_table = 'adm_device_definition' THEN '耗材' WHEN aci.product_table = 'wkf_activity_definition' THEN '医疗服务' WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN '挂号' WHEN def.type_code LIKE '101%' THEN '挂号' WHEN def.type_code LIKE '100%' THEN '医疗服务' WHEN def.type_code LIKE '200%' THEN '药品' WHEN def.type_code LIKE '3%' THEN '耗材' ELSE '其他' END AS feeCategoryDisplay, CASE WHEN aci.product_table = 'med_medication_definition' THEN COALESCE(def.type_code, '2000') WHEN aci.product_table = 'adm_device_definition' THEN COALESCE(def.type_code, '3000') WHEN aci.product_table = 'wkf_activity_definition' THEN COALESCE(def.type_code, '1000') WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN COALESCE(def.type_code, '1010') ELSE COALESCE(def.type_code, '9999') END AS subCategoryCode, CASE WHEN aci.product_table = 'med_medication_definition' THEN '药品' WHEN aci.product_table = 'adm_device_definition' THEN '耗材' WHEN aci.product_table = 'wkf_activity_definition' THEN '医疗服务' WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN '挂号' WHEN def.type_code LIKE '101%' THEN '挂号' WHEN def.type_code LIKE '100%' THEN '医疗服务' WHEN def.type_code LIKE '200%' THEN '药品' WHEN def.type_code LIKE '3%' THEN '耗材' ELSE '其他' END AS subCategoryDisplay, CASE WHEN aci.product_table IS NULL AND aci.generate_source_enum = 'registration' THEN COALESCE(def.charge_name, '挂号费') ELSE COALESCE(wkf.name, med.name, dev.name, def.charge_name, '未命名项目') END AS productName, COALESCE(wkf.bus_no, med.bus_no, dev.bus_no) AS productCode, NULL AS specification, aci.quantity_value AS quantityValue, COALESCE( (SELECT tc.display FROM ter_concept tc WHERE tc.code_system_id = 279125561775755265 AND tc.is_deleted = 0 AND tc.is_active = 1 AND tc.code = COALESCE(wkf.def_encounter_unit_code, med.def_encounter_unit_code, dev.def_encounter_unit_code) LIMIT 1), (SELECT tc.display FROM ter_concept tc WHERE tc.code_system_id = 279125561775755265 AND tc.is_deleted = 0 AND tc.is_active = 1 AND tc.code = aci.quantity_unit LIMIT 1), aci.quantity_unit ) AS quantityUnitDisplay, aci.unit_price AS unitPrice, CAST(doc.id AS CHAR) AS orderingDoctorId, doc.name AS orderingDoctorName, COALESCE(CAST(cashier.id AS CHAR), CAST(prac_cashier.id AS CHAR)) AS cashierId, COALESCE(cashier.name, prac_cashier.name) AS cashierName, DATE_FORMAT(rec.bill_date, '%Y-%m-%d %H:%i:%s') AS billDate, CASE WHEN aci.refund_id IS NOT NULL THEN 'REFUND' ELSE 'CHARGE' END AS tradeDirection, aci.generate_source_enum AS sourceDisplay, enc.yb_class_text AS insuranceLevelDisplay, def.yb_type AS insuranceTypeDisplay, CASE WHEN COALESCE(aci.base_amount, 0) = 0 THEN '0%' ELSE CONCAT(ROUND((aci.base_amount - aci.discount_amount) / aci.base_amount * 100, 0), '%') END AS discountRateDisplay,
,
ORDER BY rec.bill_date DESC, aci.id DESC
